import sys; sys.path.insert(0,'.')
from xg import *
d=D(); d.c('init xg/sys xg/save')
for k,v in [('pcsx_rearmed_bios','HLE'),('pcsx_rearmed_memcard1','libretro'),('pcsx_rearmed_memcard2','disabled')]: d.c('var %s %s'%(k,v))
d.c('load xg/disc1.chd xg/save/n2.srm 2'); d.c('loadstate xg/natob_room.state'); d.c('xga 0 23 xg/xga.bin'); d.c('run 2')
print('before: slot',d.c('read 800501fc 4'),'prog area',d.c('read 80017400 8'))
print('xga on ->',d.c('xga 1 23 xg/xga.bin')); d.c('run 5'); print(' slot',d.c('read 800501fc 4'),'opts',d.c('read 80017f04 5'))
d.c('axes 0 0 30000 0'); o0=d.c('read 800afa0c 4'); d.c('run 40'); print(' right stick orbit target',o0,'->',d.c('read 800afa0c 4')); d.c('axes 0 0 0 0'); d.c('run 20')
d.c('axes -20000 20000 0 0'); d.c('run 6'); print(' dir table pushed',d.c('read 800adf68 8')); d.c('axes 0 0 0 0'); d.c('run 10')
print('xga off ->',d.c('xga 0 23')); d.c('run 3'); print(' slot',d.c('read 800501fc 4'))
d.c('axes -20000 20000 0 0'); d.c('run 6'); print(' dir table pushed (off)',d.c('read 800adf68 8')); d.c('axes 0 0 0 0'); d.c('run 10')
print('xga on ->',d.c('xga 1 23')); d.c('run 3'); print(' slot',d.c('read 800501fc 4'),'state',d.c('xgastate'))
d.c('save xg/n2_on.state'); print('loadstate', d.c('loadstate xg/clean_field.state')); d.c('run 3'); print(' after loading a state without it: slot',d.c('read 800501fc 4'),'state',d.c('xgastate'))
d.c('cheat 0 1 80017800 1234'); d.c('run 2'); print('game data in block -> state',d.c('xgastate'),'slot',d.c('read 800501fc 4')); d.c('clearcheats'); d.c('run 5'); print(' still',d.c('xgastate'),d.c('read 800501fc 4'))
d.c('run 120'); d.shot('n2_end'); print('prog', d.c('read 8006faf0 4')); d.c('quit')
